<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import AppButton from '@/components/AppButton.vue'
import AppIcon from '@/components/AppIcon.vue'
import AppNavbar from '@/components/AppNavbar.vue'
import AppPage from '@/components/AppPage.vue'
import BaseCard from '@/components/BaseCard.vue'
import BottomActionBar from '@/components/BottomActionBar.vue'
import StatusTag from '@/components/StatusTag.vue'
import StepProgress from '@/components/StepProgress.vue'
import { usePageResource } from '@/composables/usePageResource'
import { merchantTradeService } from '@/services/trade'
import { openSubPage } from '@/utils/navigation'

const orderId = ref('')
const remark = ref('')
const { status, data, errorMessage, load } = usePageResource(async () => { const order = await merchantTradeService.getOrder(orderId.value); remark.value = order.merchantRemark || ''; return order })
const money = (value: number) => (value / 100).toFixed(2)
const displayStatus = computed(() => { const order = data.value; if (!order) return ''; if (order.tradeStatus === '已完成') return '已完成'; if (!['Mock成功', '支付成功'].includes(order.paymentStatus)) return '待支付'; return order.fulfillmentStatus })
const steps = computed(() => data.value?.fulfillmentMethod === '商户配送' ? ['待备货', '待配送', '配送中', '已送达', '已完成'] : data.value?.fulfillmentMethod === '社区自提' ? ['待备货', '待自提', '已核销', '已完成'] : ['待核销', '已核销', '已完成'])
const current = computed(() => { const value = displayStatus.value; const map: Record<string, number> = { '待备货':1, '待配送':2, '配送中':3, '已送达':4, '待自提':2, '待核销':1, '已核销':2, '已完成':steps.value.length }; return map[value] || 1 })
const actionLabel = computed(() => displayStatus.value === '待备货' ? '完成备货' : displayStatus.value === '待配送' ? '开始配送' : displayStatus.value === '配送中' ? '标记送达' : ['待自提', '待核销'].includes(displayStatus.value) ? '去核销' : '')
const fulfill = async () => {
  if (!data.value) return
  if (['待自提', '待核销'].includes(displayStatus.value)) { openSubPage(`/pages/verification/index?code=${data.value.verificationCode || ''}`); return }
  const action = displayStatus.value === '待备货' ? 'finish-preparing' : displayStatus.value === '待配送' ? 'start-delivery' : displayStatus.value === '配送中' ? 'mark-delivered' : undefined
  if (!action) return
  try { await merchantTradeService.fulfill(data.value.id, action); uni.showToast({ title: `${actionLabel.value}成功`, icon: 'success' }); load() } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '操作失败', icon: 'none' }); load() }
}
const saveRemark = async () => { if (!data.value) return; try { await merchantTradeService.saveRemark(data.value.id, remark.value); uni.showToast({ title: '商户备注已保存', icon: 'success' }); load() } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '保存失败', icon: 'none' }) } }
const mask = (mobile: string) => `${mobile.slice(0, 3)}****${mobile.slice(-4)}`
onLoad((options) => { orderId.value = typeof options?.id === 'string' ? options.id : ''; load() }); onShow(load)
</script>

<template>
  <AppPage :status="status" :state-message="errorMessage" secondary :with-bottom-action="true" @retry="load">
    <template #navbar><AppNavbar title="订单详情" centered show-back /></template>
    <view v-if="data" class="stack merchant-detail-page"><BaseCard class="merchant-status"><view><StatusTag tone="pending">{{ displayStatus }}</StatusTag><text>{{ data.fulfillmentMethod }}</text></view><text>订单号 {{ data.no }} · 下单 {{ data.createdAt }}</text></BaseCard><BaseCard><view class="section-title"><AppIcon name="car" :size="20" /><text>履约流程：{{ data.fulfillmentMethod }}</text></view><StepProgress :steps="steps" :current="current" :completed="Math.max(0, current - 1)" /><view class="timeline"><view v-for="event in data.timeline" :key="`${event.time}${event.title}`"><text>{{ event.title }}</text><text>{{ event.description }}</text><text>{{ event.time }}</text></view></view></BaseCard><BaseCard><view class="section-title"><AppIcon :name="data.fulfillmentMethod === '商户配送' ? 'location' : 'store'" :size="20" /><text>{{ data.fulfillmentMethod === '商户配送' ? '收货与送达信息' : '自提/核销信息' }}</text></view><view v-if="data.fulfillmentMethod === '商户配送'" class="info-block"><text>{{ data.memberName }} {{ mask(data.memberMobile) }}</text><text>{{ data.addressSnapshot?.region }}{{ data.addressSnapshot?.detail }}</text><text v-if="data.buyerRemark" class="remark">特别叮嘱：{{ data.buyerRemark }}</text></view><view v-else class="info-block"><text>{{ data.pickupPoint }}</text><text>居民：{{ data.memberName }} {{ mask(data.memberMobile) }}</text><text>核销码：{{ data.verificationCode }}（{{ data.verificationStatus }}）</text></view></BaseCard><BaseCard><view class="section-title"><AppIcon name="bag" :size="20" /><text>订购商品明细</text></view><view v-for="item in data.items" :key="item.skuId" class="product-row"><image :src="item.productImage" mode="aspectFill" /><view><text>{{ item.productName }}</text><text>{{ item.skuName }}</text><text>¥{{ money(item.unitPrice) }} × {{ item.quantity }}</text></view></view><view class="money-row"><text>商品小计</text><text>¥{{ money(data.goodsAmount) }}</text></view><view class="money-row"><text>配送费</text><text>¥{{ money(data.deliveryFee) }}</text></view></BaseCard><BaseCard><view class="section-title"><AppIcon name="bill" :size="20" /><text>结算与资金状态</text></view><view class="money-hero"><text>居民实付金额</text><text>¥{{ money(data.paidAmount || data.payableAmount) }}</text><StatusTag tone="pending">{{ data.profitSharingStatus }}</StatusTag></view><view class="plain-row"><text>支付状态</text><text>{{ data.paymentStatus }}</text></view><view class="plain-row"><text>售后状态</text><text>{{ data.afterSaleStatus }} · {{ data.refundStatus }}</text></view></BaseCard><BaseCard><view class="section-title"><AppIcon name="message" :size="20" /><text>商户备注</text></view><textarea v-model="remark" maxlength="200" auto-height placeholder="仅商户和平台处理人员可见" /><view class="remark-save" @click="saveRemark">保存备注</view></BaseCard></view>
    <BottomActionBar><AppButton v-if="actionLabel" @click="fulfill">{{ actionLabel }}</AppButton><AppButton v-else variant="secondary" @click="openSubPage('/pages/order/index')">返回订单列表</AppButton></BottomActionBar>
  </AppPage>
</template>

<style scoped lang="scss">
.merchant-detail-page { gap:$space-3; }.merchant-status { display:flex; flex-direction:column; gap:$space-2; background:$color-primary; color:#fff; }.merchant-status > view { display:flex; align-items:center; gap:$space-2; }.merchant-status :deep(.status-tag) { min-height:24px; border:1px solid rgba(255,255,255,.45); background:rgba(255,255,255,.14); color:#fff; }.merchant-status > text { color:rgba(255,255,255,.8); font-size:13px; }.section-title { display:flex; align-items:center; gap:$space-2; padding-bottom:$space-3; border-bottom:1px solid rgba(225,228,230,.72); font-size:17px; font-weight:700; }.timeline { display:flex; flex-direction:column; gap:$space-3; padding:$space-3 0 0 $space-2; }.timeline > view { position:relative; display:flex; flex-direction:column; gap:2px; padding-left:$space-3; color:$color-text-secondary; font-size:12px; line-height:18px; }.timeline > view::before { position:absolute; top:5px; left:0; width:7px; height:7px; border-radius:50%; background:$color-primary; content:''; }.timeline text:first-child { color:$color-text-primary; font-size:14px; font-weight:600; }.timeline text:last-child { color:$color-text-disabled; }.info-block { display:flex; flex-direction:column; gap:$space-2; padding-top:$space-3; font-size:15px; line-height:22px; }.info-block text:first-child { font-size:17px; font-weight:700; }.remark { padding:$space-2; border-radius:$radius-sm; background:$color-warning-light; color:$color-warning; }.product-row { display:flex; align-items:center; gap:$space-3; padding:$space-3 0; border-bottom:1px solid rgba(225,228,230,.72); }.product-row image { width:64px; height:64px; border-radius:$radius-md; background:$color-group-bg; }.product-row > view { display:flex; flex:1; flex-direction:column; gap:3px; }.product-row text:first-child { font-size:16px; font-weight:600; }.product-row text:not(:first-child) { color:$color-text-secondary; font-size:13px; }.product-row text:last-child { color:$color-accent; font-size:15px; font-weight:700; }.money-row,.plain-row { display:flex; align-items:center; justify-content:space-between; gap:$space-3; padding-top:$space-3; color:$color-text-secondary; font-size:14px; }.money-row text:last-child,.plain-row text:last-child { color:$color-text-primary; }.money-hero { display:flex; align-items:baseline; flex-wrap:wrap; gap:$space-2; margin-top:$space-3; padding:$space-3; border-radius:$radius-md; background:$color-group-bg; }.money-hero text:first-child { color:$color-text-secondary; font-size:13px; }.money-hero text:nth-child(2) { flex:1; color:$color-accent; font-size:27px; font-weight:700; }.money-hero :deep(.status-tag) { min-height:22px; padding:0 6px; border-radius:999px; font-size:12px; } textarea { width:100%; min-height:64px; margin-top:$space-3; padding:$space-3; border-radius:$radius-md; background:$color-group-bg; font-size:14px; line-height:20px; }.remark-save { display:flex; width:96px; height:36px; align-items:center; justify-content:center; margin:$space-3 0 0 auto; border-radius:$radius-md; background:$color-primary-light; color:$color-primary; font-size:13px; font-weight:600; }
</style>
